    h, w = len(a), len(a[0])
    divider = next(c for c in range(w) if a[0][c] != 0 and all(a[r][c] == a[0][c] for r in range(h)))
    drawings = []
    for color in set(a[r][c] for r in range(h) for c in range(divider)) - {0}:
        pixels = [(r, c) for r in range(h) for c in range(divider) if a[r][c] == color]
        rows = [r for r in range(h) if a[r][divider + 1] == color]
        cols = [c for c in range(divider + 1, w) if a[0][c] == color]
        if not rows or not cols:
            continue
        r0, r1 = min(r for r, c in pixels), max(r for r, c in pixels)
        c0, c1 = min(c for r, c in pixels), max(c for r, c in pixels)
        for r, c in pixels:
            a[r][c] = 0
        for r in rows:
            for c in cols:
                for pr, pc in pixels:
                    rr = r + pr - (r0 + r1) // 2
                    cc = c + pc - (c0 + c1) // 2
                    drawings.append((rr, cc, color))
    for r, c, color in drawings:
        a[r][c] = color
    return a
